changeSet.sql:
-- Mother tables: join on patient_uuid (works whether pmtct_cycle_id exists or not)
UPDATE pmtct_anc a SET pmtct_cycle_uuid = pc.uuid FROM pmtct_pregnancy_cycle pc WHERE a.patient_uuid = pc.patient_uuid AND a.pmtct_cycle_uuid IS NULL;
UPDATE pmtct_enrollment e SET pmtct_cycle_uuid = pc.uuid FROM pmtct_pregnancy_cycle pc WHERE e.patient_uuid = pc.patient_uuid AND e.pmtct_cycle_uuid IS NULL;
UPDATE pmtct_delivery d SET pmtct_cycle_uuid = pc.uuid FROM pmtct_pregnancy_cycle pc WHERE d.patient_uuid = pc.patient_uuid AND d.pmtct_cycle_uuid IS NULL;
UPDATE pmtct_hts h SET pmtct_cycle_uuid = pc.uuid FROM pmtct_pregnancy_cycle pc WHERE h.patient_uuid = pc.patient_uuid AND h.pmtct_cycle_uuid IS NULL;
UPDATE pmtct_mother_visitation mv SET pmtct_cycle_uuid = pc.uuid FROM pmtct_pregnancy_cycle pc WHERE mv.patient_uuid = pc.patient_uuid AND mv.pmtct_cycle_uuid IS NULL;
-- Infant tables: join on mother_patient_uuid
UPDATE pmtct_infant_information ii SET pmtct_cycle_uuid = pc.uuid FROM pmtct_pregnancy_cycle pc WHERE ii.mother_patient_uuid = pc.patient_uuid AND ii.pmtct_cycle_uuid IS NULL;
UPDATE pmtct_infant_visit iv SET pmtct_cycle_uuid = pc.uuid FROM pmtct_pregnancy_cycle pc WHERE iv.mother_patient_uuid = pc.patient_uuid AND iv.pmtct_cycle_uuid IS NULL;
UPDATE pmtct_infant_arv ia SET pmtct_cycle_uuid = pc.uuid FROM pmtct_pregnancy_cycle pc WHERE ia.mother_patient_uuid = pc.patient_uuid AND ia.pmtct_cycle_uuid IS NULL;
UPDATE pmtct_infant_pcr ip SET pmtct_cycle_uuid = pc.uuid FROM pmtct_pregnancy_cycle pc WHERE ip.mother_patient_uuid = pc.patient_uuid AND ip.pmtct_cycle_uuid IS NULL;
UPDATE pmtct_infant_mother_art ima SET pmtct_cycle_uuid = pc.uuid FROM pmtct_pregnancy_cycle pc WHERE ima.mother_patient_uuid = pc.patient_uuid AND ima.pmtct_cycle_uuid IS NULL;
UPDATE pmtct_infant_rapid_antibody ira SET pmtct_cycle_uuid = pc.uuid FROM pmtct_pregnancy_cycle pc WHERE ira.mother_patient_uuid = pc.patient_uuid AND ira.pmtct_cycle_uuid IS NULL;

ALTER TABLE pmtct_anc DROP COLUMN IF EXISTS pmtct_cycle_id;
ALTER TABLE pmtct_enrollment DROP COLUMN IF EXISTS pmtct_cycle_id;
ALTER TABLE pmtct_delivery DROP COLUMN IF EXISTS pmtct_cycle_id;
ALTER TABLE pmtct_hts DROP COLUMN IF EXISTS pmtct_cycle_id;
ALTER TABLE pmtct_mother_visitation DROP COLUMN IF EXISTS pmtct_cycle_id;
ALTER TABLE pmtct_infant_information DROP COLUMN IF EXISTS pmtct_cycle_id;
ALTER TABLE pmtct_infant_visit DROP COLUMN IF EXISTS pmtct_cycle_id;
ALTER TABLE pmtct_infant_arv DROP COLUMN IF EXISTS pmtct_cycle_id;
ALTER TABLE pmtct_infant_pcr DROP COLUMN IF EXISTS pmtct_cycle_id;
ALTER TABLE pmtct_infant_mother_art DROP COLUMN IF EXISTS pmtct_cycle_id;
ALTER TABLE pmtct_infant_rapid_antibody DROP COLUMN IF EXISTS pmtct_cycle_id;
